function twoRows(component: string, offsets: number[], leftX: number, rightX: number, labels: string[]) {
  return offsets.flatMap((z, index) => ([
    { id: `${component}-left-${index + 1}`, label: labels[index] ?? `L${index + 1}`, side: 'left' as const, index, local3d: [leftX, 0.25, z] as [number, number, number], description: 'Terminal físico; serigrafia e função elétrica ainda precisam ser confirmadas na placa real.', verification: 'pending' as const },
    { id: `${component}-right-${index + 1}`, label: labels[index] ?? `R${index + 1}`, side: 'right' as const, index, local3d: [rightX, 0.25, z] as [number, number, number], description: 'Terminal físico; serigrafia e função elétrica ainda precisam ser confirmadas na placa real.', verification: 'pending' as const },
  ]));
}

