export function componentById(id: HardwareComponent['id']) { return hardware.find((component) => component.id === id)!; }
export function pinById(componentId: HardwareComponent['id'], pinId: string) { return componentById(componentId).pins.find((pin) => pin.id === pinId)!; }
export function worldPinPosition(componentId: HardwareComponent['id'], pinId: string): [number, number, number] {
  const component = componentById(componentId); const pin = pinById(componentId, pinId);
  return [component.worldPosition[0] + pin.local3d[0], component.worldPosition[1] + pin.local3d[1], component.worldPosition[2] + pin.local3d[2]];
}
